    41|/** Bounded loop: max LLM revision iterations before BLOCKED. */
    42|const MAX_ITERATIONS = 6;
    43|/** Per-command timeout (ms). */
    44|const COMMAND_TIMEOUT_MS = 60_000;
    45|/** LLM planning timeout (ms). The Render runtime was hanging in the planning
    46| * phase indefinitely; this hard cap ensures the loop progresses or BLOCKS with
    47| * a real reason instead of sitting at RUNNING 10% forever. */
    48|const LLM_TIMEOUT_MS = 90_000;
    49|/** LLM planning attempts before LLM_PLAN_INVALID BLOCKED. */
    50|const MAX_LLM_ATTEMPTS = 4;
    51|/** Stage-specific timeouts (ms) — each bounded loop stage has its own hard cap
    52| * so a stuck inspection / patch / test / commit / deploy is detectable and the
    53| * engine BLOCKS with a real reason instead of hanging forever. These are
    54| * checked between stages via the wall-clock elapsed-since-stage-start timer. */
    55|const STAGE_TIMEOUTS_MS: Record<string, number> = {
    56|  inspecting: 30_000,
    57|  planning: LLM_TIMEOUT_MS + 5_000,
    58|  patching: 120_000,
    59|  testing: 90_000,
    60|  analyzing: 5_000,
    61|  revising: 5_000,
    62|  verifying: 15_000,
    63|  committing: 30_000,
    64|  awaiting_owner_approval: 5_000,
    65|  deploying: 30_000,
    66|  production_verifying: 45_000,
    67|};
    68|/** Max wall-clock runtime for the WHOLE job (ms). Independent of per-iteration
    69| * and per-stage limits — a global kill switch so a runaway job can never run
    70| * unbounded. Default 8 minutes; override via input.maxRuntimeMs. */
    71|const DEFAULT_MAX_RUNTIME_MS = 15 * 60_000; // V6.15: 8→15 min — 4 iterations with baseline+post-patch typecheck need more room
    72|/** Max LLM calls per job (across all iterations + attempts). Independent of
    73| * MAX_ITERATIONS — a cost cap so the engine can never burn unbounded tokens. */
    74|const DEFAULT_MAX_LLM_CALLS = MAX_ITERATIONS * MAX_LLM_ATTEMPTS;
    75|/** Max estimated tokens per job (soft cap — tracked from LLM response lengths).
    76| * If the cumulative estimated token count exceeds this, the engine BLOCKS with
    77| * TOKEN_BUDGET_EXCEEDED rather than making another call. 200k is realistic for a
    78| * real coding task with up to 5 iterations (each iteration sends file previews +
    79| * a patch response). The 60k cap was too tight and BLOCKED a legitimate PILOT-3
    80| * change after 4 iterations. */
    81|const DEFAULT_MAX_TOKEN_BUDGET = 400_000;
